/* ═══ RENDER ═══ */
function renderWorkspace(){
  const grid=document.getElementById("moduleGrid");
  if(!grid)return;
  grid.innerHTML=MODS.map(m=>{
    const pct=S.modProgress[m.id]||0;
    const locked=m.pkg==="growth"&&S.pkg==="foundation"||m.pkg==="domination"&&S.pkg!=="domination";
    return`<div class="mod-tile ${pct>0&&pct<100?"active-tile":pct===100?"done-tile":locked?"locked-tile":""}" onclick="navTo('mod${m.id}')">
      <div class="mt-icon">${pct===100?"✅":m.icon}</div>
      <div class="mt-info">
        <div class="mt-num">Module ${m.id+1}</div>
        <div class="mt-name">${m.title}</div>
        <div class="mt-desc">${m.desc}</div>
        <div class="mt-meta">
          <span class="mt-tag ${m.pkg==="foundation"?"mt-free":m.pkg==="growth"?"mt-growth":"mt-dom"}">${m.pkg==="foundation"?"FREE":m.pkg==="growth"?"GROWTH":"DOMINATION"}</span>
          ${pct===100?'<span class="mt-tag" style="background:var(--gd);color:var(--green);">✓ COMPLETE</span>':''}
          ${locked?'<span class="mt-tag" style="background:var(--rd);color:var(--red);">🔒 LOCKED</span>':''}
        </div>
      </div>
      <div class="mt-progress"><div class="mt-progress-fill" style="width:${pct}%"></div></div>
    </div>`;
  }).join("");
}

function renderModuleScreen(modIdx){
  const m=MODS[modIdx];
  const el=document.getElementById("screen-mod"+modIdx);
  const locked=m.pkg==="growth"&&S.pkg==="foundation"||m.pkg==="domination"&&S.pkg!=="domination";

  const tasksHtml=m.tasks.map((t,ti)=>{
    const key=`mod${modIdx}_task${ti}`;
    const isDone=S.tasksDone[key]||false;
    const hasOutput=S.assets[key];
    return`<div class="agent-task ${isDone?"complete":""}" id="at_${modIdx}_${ti}">
      <div class="at-header" onclick="toggleTask(${modIdx},${ti})">
        <div class="at-status" id="ats_${modIdx}_${ti}">${isDone?"✓":ti+1}</div>
        <div class="at-info">
          <div class="at-name">${t.name}</div>
          <div class="at-hint">${t.hint}</div>
        </div>
        <span class="at-badge ${isDone?"atb-done":"atb-wait"}" id="atb_${modIdx}_${ti}">${isDone?"DONE":"READY"}</span>
        <span class="at-chevron" id="atc_${modIdx}_${ti}">▼</span>
      </div>
      <div class="at-progress"><div class="at-progress-fill" id="atp_${modIdx}_${ti}" style="width:${isDone?100:0}%"></div></div>
      <div class="at-body" id="atbody_${modIdx}_${ti}" style="display:none;">
        <div class="task-fields">
          ${renderFields(t.fields,modIdx,ti)}
        </div>
        <div style="display:flex;gap:.75rem;align-items:center;flex-wrap:wrap;">
          <button class="run-btn" id="runbtn_${modIdx}_${ti}" onclick="runTask(${modIdx},${ti})">
            <span class="run-icon" id="runicon_${modIdx}_${ti}">✦</span>
            Generate
          </button>
          ${hasOutput?`<button class="btn btn-outline btn-sm" onclick="copyAsset('${key}')">Copy Output</button>`:""}
        </div>
        ${hasOutput?renderOutput(key,modIdx,ti):""}
        ${hasOutput&&!isDone?`<button class="mark-done-btn" onclick="markDone(${modIdx},${ti})">✓ Mark complete</button>`:""}
      </div>
    </div>`;
  }).join("");

  const lockedHtml=locked?`<div style="background:var(--rd);border:1px solid rgba(240,80,110,.25);border-radius:12px;padding:1.25rem;text-align:center;margin-bottom:1.25rem;">
    <div style="font-size:1.5rem;margin-bottom:.5rem;">🔒</div>
    <div style="font-family:'Syne',sans-serif;font-weight:700;font-size:.95rem;margin-bottom:.35rem;">Upgrade Required</div>
    <p style="font-size:.82rem;color:var(--text);line-height:1.55;margin-bottom:.9rem;">This module requires the ${m.pkg==="growth"?"Growth (£49/mo)":"Domination (£97/mo)"} plan.</p>
    <button class="btn btn-primary btn-sm" onclick="navTo('pricing')">See Plans →</button>
  </div>`:"";

  el.innerHTML=`
    <div class="agent-header">
      <div class="ah-cat">${m.cat}</div>
      <div class="ah-title">${m.icon} ${m.title}</div>
      <div class="ah-desc">${m.desc}</div>
      <div class="ah-tags">
        <span class="atag" style="background:var(--${m.pkg==="foundation"?"gd":m.pkg==="growth"?"cd":"pd"});color:var(--${m.pkg==="foundation"?"green":m.pkg==="growth"?"cyan":"purple"});">${m.pkg.toUpperCase()}</span>
        <span class="atag" style="background:rgba(255,255,255,.06);color:var(--dim);">${m.tasks.length} agents</span>
        <span class="atag" style="background:var(--cd);color:var(--cyan);">Shanaz</span>
      </div>
    </div>
    ${lockedHtml}
    <div style="display:flex;gap:.75rem;align-items:center;margin-bottom:1.25rem;flex-wrap:wrap;">
      <button class="run-all-btn" onclick="runAllTasks(${modIdx})" ${locked?"disabled":""}>
        <span>⚡</span> Run All ${m.tasks.length} Agents
      </button>
      <button class="btn btn-outline btn-sm" onclick="navTo('workspace')">← Workspace</button>
    </div>
    <div class="agent-chain" id="chain_${modIdx}">${tasksHtml}</div>
    <div class="dfy">
      <div class="dfy-txt"><strong>${m.dfy.l}</strong><p>${m.dfy.d}</p></div>
      <a href="${m.dfy.u}" target="_blank" class="btn btn-dfy">${m.dfy.cta}</a>
    </div>`;
}

function renderFields(fields,mi,ti){
  const cols=fields.length>=4?"bf-grid":"";
  return`<div class="${cols}">
    ${fields.map(f=>`<div class="fg ${fields.length>=4&&f.type!=="textarea"?"":""}">
      <label>${f.l}</label>
      ${f.type==="textarea"
        ?`<textarea id="f_${mi}_${ti}_${f.id}" placeholder="${f.ph}" style="min-height:64px;"></textarea>`
        :`<input id="f_${mi}_${ti}_${f.id}" placeholder="${f.ph}" type="text">`}
    </div>`).join("")}
  </div>`;
}

function renderOutput(key,mi,ti){
  const text=S.assets[key]||"";
  const isCode=text.trim().startsWith("{")&&text.includes('"@context"');
  return`<div class="task-output">
    <div class="to-header">
      <span class="to-label">Your Output</span>
      <div class="to-actions">
        <button class="to-btn" onclick="copyAsset('${key}')">Copy</button>
        <button class="to-btn" onclick="rerunTask(${mi},${ti})">Regenerate</button>
      </div>
    </div>
    <div class="to-content ${isCode?"code":""}" id="out_${mi}_${ti}">${escH(text)}</div>
  </div>`;
}

/* ═══ TASK EXECUTION ═══ */
function toggleTask(mi,ti){
  const body=document.getElementById(`atbody_${mi}_${ti}`);
  const chev=document.getElementById(`atc_${mi}_${ti}`);
  const task=document.getElementById(`at_${mi}_${ti}`);
  if(!body)return;
  const open=body.style.display!=="none";
  body.style.display=open?"none":"block";
  if(chev)chev.style.transform=open?"":"rotate(180deg)";
  task.classList.toggle("open",!open);
}

function getFieldVals(t,mi,ti){
  const vals={};
  t.fields.forEach(f=>{
    const el=document.getElementById(`f_${mi}_${ti}_${f.id}`);
    if(el)vals[f.id]=el.value.trim();
  });
  return vals;
}

async function runTask(mi,ti){
  const m=MODS[mi];
  const t=m.tasks[ti];
  const btn=document.getElementById(`runbtn_${mi}_${ti}`);
  const icon=document.getElementById(`runicon_${mi}_${ti}`);
  const taskEl=document.getElementById(`at_${mi}_${ti}`);
  const badge=document.getElementById(`atb_${mi}_${ti}`);
  const progFill=document.getElementById(`atp_${mi}_${ti}`);

  const fieldVals=getFieldVals(t,mi,ti);

  // Require at least 1 field to be filled for non-empty tasks
  const hasInput=Object.values(fieldVals).some(v=>v.length>0);
  const requiredFields=t.fields.filter(f=>!f.optional);
  if(requiredFields.length>0&&!hasInput){
    showToast("Fill in at least one field 👆","#f5a623");
    return;
  }

  btn.disabled=true;
  if(icon)icon.textContent="⟳";
  btn.classList.add("running");
  taskEl.classList.add("running");
  if(badge){badge.textContent="RUNNING";badge.className="at-badge atb-run";}
  if(progFill)progFill.style.width="15%";

  // Animated progress
  let prog=15;
  const progInt=setInterval(()=>{
    prog=Math.min(90,prog+Math.random()*8);
    if(progFill)progFill.style.width=prog+"%";
  },600);

  try{
    const prompt=t.prompt(fieldVals,S);
    const result=await callClaude(prompt);
    clearInterval(progInt);
    if(progFill)progFill.style.width="100%";

    const key=`mod${mi}_task${ti}`;
    S.assets[key]=result;

    // Map to asset library
    mapToAsset(mi,ti,result);

    // Update asset count
    updateAssetCount();

    // Show output with streaming effect
    const body=document.getElementById(`atbody_${mi}_${ti}`);
    if(body){
      // Remove old output
      const old=body.querySelector(".task-output");
      if(old)old.remove();
      const oldMark=body.querySelector(".mark-done-btn");
      if(oldMark)oldMark.remove();

      const isCode=result.trim().startsWith("{")&&result.includes('"@context"');
      const outDiv=document.createElement("div");
      outDiv.innerHTML=`<div class="task-output" style="animation:fadeUp .35s ease both;">
        <div class="to-header">
          <span class="to-label">Your Output</span>
          <div class="to-actions">
            <button class="to-btn" onclick="copyAsset('${key}')">Copy</button>
            <button class="to-btn" onclick="rerunTask(${mi},${ti})">Regenerate</button>
          </div>
        </div>
        <div class="to-content ${isCode?"code":""}" id="out_${mi}_${ti}"></div>
      </div>`;
      body.appendChild(outDiv);

      // Stream
      streamText(`out_${mi}_${ti}`,result);

      // Add mark done button
      setTimeout(()=>{
        const mb=document.createElement("button");
        mb.className="mark-done-btn";
        mb.innerHTML="✓ Mark complete";
        mb.onclick=()=>markDone(mi,ti);
        body.appendChild(mb);
      },1000);
    }

    if(badge){badge.textContent="DONE";badge.className="at-badge atb-done";}
    showToast(`${t.name} generated ✓`);
  }catch(err){
    clearInterval(progInt);
    taskEl.classList.remove("running");
    taskEl.classList.add("error");
    if(badge){badge.textContent="ERROR";badge.className="at-badge atb-err";}
    showToast("Connection error please try again","var(--red)");
    console.error(err);
  }finally{
    btn.disabled=false;
    if(icon)icon.textContent="✦";
    btn.classList.remove("running");
    taskEl.classList.remove("running");
  }
}

async function runAllTasks(mi){
  const m=MODS[mi];
  showToast(`Running all ${m.tasks.length} agents for Module ${mi+1}...`,"#5bc8f5");
  for(let ti=0;ti<m.tasks.length;ti++){
    // Open task
    const body=document.getElementById(`atbody_${mi}_${ti}`);
    if(body&&body.style.display==="none"){
      toggleTask(mi,ti);
    }
    await runTask(mi,ti);
    await new Promise(r=>setTimeout(r,800));
  }
  updateModProgress(mi);
  showToast(`Module ${mi+1} complete all assets generated! 🎉`);
  fireConfetti();
}

function markDone(mi,ti){
  const key=`mod${mi}_task${ti}`;
  S.tasksDone[key]=true;
  const taskEl=document.getElementById(`at_${mi}_${ti}`);
  const badge=document.getElementById(`atb_${mi}_${ti}`);
  const statEl=document.getElementById(`ats_${mi}_${ti}`);
  if(taskEl){taskEl.classList.remove("running","error");taskEl.classList.add("complete");}
  if(badge){badge.textContent="DONE";badge.className="at-badge atb-done";}
  if(statEl)statEl.textContent="✓";
  updateModProgress(mi);
  updateScore();
}

async function rerunTask(mi,ti){
  const key=`mod${mi}_task${ti}`;
  delete S.assets[key];
  S.tasksDone[key]=false;
  await runTask(mi,ti);
}

function updateModProgress(mi){
  const m=MODS[mi];
  const total=m.tasks.length;
  const done=m.tasks.filter((_,ti)=>S.tasksDone[`mod${mi}_task${ti}`]).length;
  const pct=Math.round((done/total)*100);
  S.modProgress[mi]=pct;
  const np=document.getElementById("np"+mi);
  if(np)np.style.width=pct+"%";
  renderWorkspace();
}

/* ═══ WEBSITE AUDIT ═══ */
async function runWebsiteAudit(){
  const url=document.getElementById("auditUrl")?.value?.trim();
  if(!url){showToast("Enter your website URL first","#f5a623");return;}

  // Basic URL validation
  let cleanUrl = url;
  if(!cleanUrl.startsWith("http://")&&!cleanUrl.startsWith("https://")){
    cleanUrl = "https://"+cleanUrl;
  }

  navTo("audit");
  const el=document.getElementById("auditContent");

  // Loading state
  el.innerHTML=`<div style="background:var(--card);border:1px solid var(--b1);border-radius:14px;padding:2rem;">
    <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.25rem;">
      <div style="width:40px;height:40px;border-radius:50%;background:var(--pd);border:2px solid var(--purple);
        display:flex;align-items:center;justify-content:center;font-size:.95rem;
        animation:spin 1s linear infinite;">⟳</div>
      <div>
        <div style="font-family:'Syne',sans-serif;font-weight:700;font-size:.95rem;">
          Reading ${cleanUrl}</div>
        <div style="font-size:.78rem;color:var(--dim);margin-top:.2rem;">
          Fetching your website then running the full AEO audit...</div>
      </div>
    </div>
    <div style="background:var(--s1);border-radius:8px;padding:.85rem;
      font-size:.78rem;color:var(--dim);line-height:1.75;">
      Step 1: Fetching your live website content...<br>
      Step 2: Analysing schema markup, content structure, voice readiness...<br>
      Step 3: Generating your personalised fix list and 30-day plan...
    </div>
  </div>`;

  try{
    // Call the dedicated audit function which fetches the site first
    const res = await fetch("/.netlify/functions/audit", {
      method: "POST",
      headers: {"Content-Type":"application/json"},
      body: JSON.stringify({
        url: cleanUrl,
        biz: S.biz||"UK SME",
        type: S.type||"business"
      })
    });

    const data = await res.json();

    if(!res.ok){
      throw new Error(data.error||"Audit request failed");
    }

    if(!data.content||!data.content[0]||!data.content[0].text){
      throw new Error("No audit content returned");
    }

    const result = data.content[0].text;
    const fetchMethod = data.fetchMethod||"unknown";

    S.assets["audit_report"]=result;
    updateAssetCount();

    // Show fetch method notice
    const methodNotice = fetchMethod==="live"
      ? `<div style="background:var(--gd);border:1px solid rgba(31,212,160,.25);border-radius:8px;
          padding:.6rem 1rem;font-size:.76rem;color:var(--green);margin-bottom:.85rem;
          display:flex;align-items:center;gap:.5rem;">
          <span>✓</span> Live audit — Shanaz read your actual website content
         </div>`
      : `<div style="background:var(--ad);border:1px solid rgba(245,166,35,.25);border-radius:8px;
          padding:.6rem 1rem;font-size:.76rem;color:var(--amber);margin-bottom:.85rem;
          display:flex;align-items:center;gap:.5rem;">
          <span>⚠</span> Your site blocked direct access — audit based on URL and business type patterns.
          Still highly accurate for ${S.type||"your sector"}.
         </div>`;

    el.innerHTML=`
      ${methodNotice}
      <div class="task-output">
        <div class="to-header">
          <span class="to-label">Website Audit — ${cleanUrl}</span>
          <div class="to-actions">
            <button class="to-btn" onclick="copyText(S.assets['audit_report'])">Copy Report</button>
          </div>
        </div>
        <div class="to-content" id="auditOutputContent"></div>
      </div>`;

    streamText("auditOutputContent", result);
    showToast("Website audit complete ✓");

  }catch(err){
    console.error("Audit error:", err);
    el.innerHTML=`
      <div style="background:var(--rd);border:1px solid rgba(240,80,110,.25);
        border-radius:12px;padding:1.5rem;text-align:center;">
        <div style="font-size:1.5rem;margin-bottom:.65rem;">⚠</div>
        <div style="font-family:'Syne',sans-serif;font-weight:700;font-size:.95rem;margin-bottom:.4rem;">
          Audit failed</div>
        <p style="font-size:.82rem;color:var(--text);line-height:1.6;margin-bottom:1rem;">
          ${err.message||"Connection error"}.<br>
          Check your URL is correct and try again.
        </p>
        <button class="btn btn-primary btn-sm" onclick="runWebsiteAudit()">Try Again</button>
      </div>`;
    showToast("Audit failed — check URL and try again","var(--red)");
  }
}

