/* ═══ ASSET LIBRARY ═══ */
function renderAssets(){
  const grid=document.getElementById("assetGrid");
  if(!grid)return;
  grid.innerHTML=ASSET_TYPES.map(a=>{
    const has=S.assets[a.key];
    return`<div class="asset-card ${has?"":"empty"}" onclick="${has?`viewAsset('${a.key}')`:""}" >
      <div class="ac-icon">${a.icon}</div>
      <div class="ac-name">${a.name}</div>
      <div class="ac-module">${a.mod}</div>
      <span class="ac-status ${has?"acs-ready":"acs-empty"}">${has?"Ready ✓":"Not generated"}</span>
    </div>`;
  }).join("");
}

function viewAsset(key){
  const text=S.assets[key]||"";
  const asset=ASSET_TYPES.find(a=>a.key===key);
  const overlay=document.createElement("div");
  overlay.style.cssText="position:fixed;inset:0;z-index:800;background:rgba(6,9,15,.96);backdrop-filter:blur(14px);display:flex;align-items:center;justify-content:center;padding:1.5rem;";
  overlay.onclick=(e)=>{if(e.target===overlay)overlay.remove();};
  overlay.innerHTML=`<div style="background:var(--card);border:1px solid var(--b1);border-radius:18px;padding:1.75rem 2rem;max-width:720px;width:100%;max-height:85vh;overflow-y:auto;position:relative;">
    <button onclick="this.closest('[style]').remove()" style="position:absolute;top:1rem;right:1rem;background:rgba(255,255,255,.06);border:1px solid var(--b1);color:var(--dim);border-radius:6px;padding:.25rem .6rem;cursor:pointer;font-size:.8rem;">✕</button>
    <div style="font-family:'Syne',sans-serif;font-weight:800;font-size:1rem;margin-bottom:.25rem;">${asset?.icon||"📄"} ${asset?.name||key}</div>
    <div style="font-size:.72rem;color:var(--dim);margin-bottom:1rem;">${asset?.mod||""} · Your Output</div>
    <div style="display:flex;gap:.5rem;margin-bottom:1rem;">
      <button onclick="copyText(S.assets['${key}'])" class="btn btn-primary btn-sm">Copy to Clipboard</button>
    </div>
    <div style="background:rgba(6,9,15,.8);border:1px solid var(--b2);border-radius:9px;padding:.85rem 1rem;font-size:.8rem;color:var(--text);line-height:1.78;white-space:pre-wrap;word-break:break-word;max-height:400px;overflow-y:auto;">${escH(text)}</div>
  </div>`;
  document.body.appendChild(overlay);
}

