/* ═══ UTILS ═══ */
async function callClaude(prompt){
  const res=await fetch("/.netlify/functions/claude",{
    method:"POST",
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({
      model:"claude-sonnet-4-20250514",
      max_tokens:1000,
      messages:[{role:"user",content:prompt}]
    })
  });
  const data=await res.json();
  if(data.content&&data.content[0]&&data.content[0].text)return data.content[0].text;
  throw new Error("No response");
}

function streamText(elId,text){
  const el=document.getElementById(elId);
  if(!el)return;
  el.innerHTML='<span class="cursor"></span>';
  let i=0;
  const interval=setInterval(()=>{
    if(i<text.length){
      el.innerHTML=escH(text.substring(0,i+4))+'<span class="cursor"></span>';
      i+=4;
      el.scrollTop=el.scrollHeight;
    }else{
      el.innerHTML=escH(text);
      clearInterval(interval);
    }
  },7);
}

function escH(s){return(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}

function copyText(text){
  navigator.clipboard.writeText(text||"").then(()=>showToast("Copied ✓","#5bc8f5"));
}

function copyAsset(key){
  copyText(S.assets[key]||"");
}

function showToast(msg,bg="var(--green)"){
  const t=document.getElementById("toast");
  t.textContent=msg;t.style.background=bg;
  t.classList.add("show");
  setTimeout(()=>t.classList.remove("show"),3300);
}

function fireConfetti(){
  const host=document.getElementById("cfhost");host.innerHTML="";
  const cols=["#5bc8f5","#1fd4a0","#f5a623","#eef6ff","#f0506e","#7b6cf6"];
  for(let i=0;i<60;i++){
    const p=document.createElement("div");p.className="cp";
    const sz=6+Math.random()*8;
    p.style.cssText=`left:${Math.random()*100}%;background:${cols[~~(Math.random()*cols.length)]};--d:${1.8+Math.random()*1.3}s;--dl:${Math.random()*.8}s;width:${sz}px;height:${sz}px;border-radius:${Math.random()>.5?"50%":"2px"};transform:rotate(${Math.random()*360}deg);`;
    host.appendChild(p);
  }
  setTimeout(()=>host.innerHTML="",4000);
}

/* ═══ NAVIGATION ═══ */
const pageTitles={
  workspace:"Workspace",assets:"Asset Library",
  mod0:"Module 1 Full AI Audit",mod1:"Module 2 Schema Suite",
  mod2:"Module 3 Content Engine",mod3:"Module 4 Authority Builder",
  mod4:"Module 5 Reputation & Monitor",mod5:"Module 6 AI Conversion",
  mod6:"Module 7 Competitor Attack",
  audit:"Website Audit",managed:"Managed Pack",pricing:"Upgrade Plan"
};

function navTo(screen){
  document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));
  document.querySelectorAll(".nav-item").forEach(n=>n.classList.remove("active"));
  const scr=document.getElementById("screen-"+screen);
  if(scr)scr.classList.add("active");
  const nav=document.getElementById("nav-"+screen);
  if(nav)nav.classList.add("active");
  const pt=document.getElementById("pageTitle");
  if(pt)pt.textContent=pageTitles[screen]||screen;

  // Render module screen if needed
  if(screen.startsWith("mod")){
    const mi=parseInt(screen.replace("mod",""));
    if(!isNaN(mi))renderModuleScreen(mi);
  }
  if(screen==="workspace")renderWorkspace();
  if(screen==="assets")renderAssets();
  window.scrollTo({top:0,behavior:"smooth"});
}

/* ═══ SCORE ═══ */
function updateScore(){
  const totalTasks=MODS.reduce((a,m)=>a+m.tasks.length,0);
  const doneTasks=Object.values(S.tasksDone).filter(Boolean).length;
  const score=Math.round((doneTasks/totalTasks)*100);
  const el=document.getElementById("sbScoreVal");
  if(el)el.textContent=score;
  const fill=document.getElementById("sbScoreFill");
  if(fill)fill.style.width=score+"%";
  const chip=document.getElementById("chipScore");
  if(chip)chip.textContent=score+"/100";
  const dot=document.getElementById("chipDot");
  if(dot)dot.style.background=score>=70?"var(--green)":score>=40?"var(--amber)":"var(--red)";
  const op=document.getElementById("opFill");
  if(op)op.style.width=score+"%";
  const opPct=document.getElementById("opPct");
  if(opPct)opPct.textContent=score+"%";
}

