function selectPkg(pkg,card){
  document.querySelectorAll(".pkg-card").forEach(c=>{
    c.classList.remove("selected");
    c.querySelector(".pkg-select-btn").textContent="Select "+c.querySelector(".pkg-name").textContent;
  });
  card.classList.add("selected");
  card.querySelector(".pkg-select-btn").textContent="Selected ✓";
  S.pkg=pkg;
  const icons={foundation:"🆓",growth:"⭐",domination:"👑"};
  const labels={foundation:"Foundation Plan",growth:"Growth Plan £49/mo",domination:"Domination Plan £97/mo"};
  const spIcon=document.getElementById("spIcon");
  const spLabel=document.getElementById("spLabel");
  if(spIcon)spIcon.textContent=icons[pkg];
  if(spLabel)spLabel.textContent=labels[pkg];
  renderWorkspace();
  showToast(`${labels[pkg]} selected!`);
}

